  /// included; otherwise every registered tool is returned.
  Map<String, dynamic> generateToolsListResponse([Set<String>? integrations]) {
    final tools = toolsForIntegrations(integrations);
    return {
      'tools': tools.map((t) => t.toJson()).toList(),
