  'jira_get_ticket',
  'jira_get_comments',
  'jira_post_comment',
  'jira_add_label',
  'jira_remove_label',
  'jira_move_to_status',
};

/// `gh-<number>` ticket key shape (lowercase, digits only).
final _ghKeyPattern = RegExp(r'^gh-(\d+)$');

/// Status names that close the issue (normalized lowercase).
const _doneStatuses = {
  'done',
  'closed',
  'resolved',
  'complete',
  'completed',
  'fixed',
  'merged',
};

/// Status names that reopen a closed issue (normalized lowercase).
const _openStatuses = {
  'open',
  'reopened',
  'todo',
  'backlog',
  'new',
  'in progress',
  'in development',
  'ready for development',
  'in review',
  'review',
