/// `gh-<number>` ticket key shape (lowercase, digits only).
final _ghKeyPattern = RegExp(r'^gh-(\d+)$');

/// Status names that close the issue (normalized lowercase).
const _doneStatuses = {
  'done',
  'closed',
  'resolved',
  'complete',
  'completed',
  'fixed',
  'merged',
};

/// Status names that reopen a closed issue (normalized lowercase).
const _openStatuses = {
  'open',
